<?php
declare(strict_types=1);
session_name('hache_public_reg');session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Lax','cookie_secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'use_strict_mode'=>true]);
$c=require __DIR__.'/../config/database.php';$pdo=new PDO("mysql:host={$c['host']};dbname={$c['dbname']};charset={$c['charset']}",$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}function digits(string $v):string{return preg_replace('/\D+/','',$v)??'';}function uid(PDO $p):string{return(string)$p->query('SELECT UUID()')->fetchColumn();}function slug(string $n):string{$a=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$n)?:$n;$a=strtolower(preg_replace('/[^a-zA-Z0-9 ]+/',' ',$a)??'');$x=array_values(array_filter(preg_split('/\s+/',trim($a))?:[]));return substr(($x[0]??'alumno').(count($x)>1?'.'.end($x):''),0,40);}function user(PDO $p,string $n):string{$b=slug($n);$u=$b;$i=2;$s=$p->prepare('SELECT 1 FROM usuarios WHERE usuario=:u');while(1){$s->execute([':u'=>$u]);if(!$s->fetchColumn())return$u;$u=$b.$i++;}}function mondays():array{$d=new DateTimeImmutable('today');if((int)$d->format('N')!==1)$d=$d->modify('next monday');$o=[];for($i=0;$i<10;$i++)$o[]=$d->modify('+'.($i*7).' days')->format('Y-m-d');return$o;}
$sede=strtoupper((string)($_GET['sede']??''));$tipo=strtoupper((string)($_GET['tipo']??''));if(!in_array($sede,['MONTEVERDE','PALAPAS'],true)||!in_array($tipo,['REGULAR','INTENSIVO'],true)){http_response_code(404);exit('Formulario no válido.');}
$st=$pdo->prepare('SELECT id,nombre FROM sedes WHERE clave=:c AND activo=1');$st->execute([':c'=>$sede]);$sd=$st->fetch();if(!$sd){http_response_code(404);exit('Sede no disponible.');}$sid=$sd['id'];$col=$tipo==='REGULAR'?'regular':'intensivo';$st=$pdo->prepare("SELECT id,hora_inicio,hora_fin FROM horarios WHERE sede_id=:s AND activo=1 AND {$col}=1 ORDER BY hora_inicio");$st->execute([':s'=>$sid]);$hor=$st->fetchAll();$lunes=mondays();if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));$err='';$ok=false;$old=['nombre'=>'','whatsapp'=>'','horario_id'=>$hor[0]['id']??'','fecha_inicio'=>$lunes[0]??''];
if($_SERVER['REQUEST_METHOD']==='POST'){foreach($old as$k=>$v)$old[$k]=trim((string)($_POST[$k]??''));try{if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Recarga el formulario e inténtalo otra vez.');if(trim((string)($_POST['website']??''))!=='')throw new RuntimeException('No se pudo procesar.');$n=preg_replace('/\s+/u',' ',trim($old['nombre']))??'';$wa=digits($old['whatsapp']);if(mb_strlen($n)<4)throw new RuntimeException('Escribe tu nombre completo.');if(strlen($wa)<10||strlen($wa)>15)throw new RuntimeException('Escribe un WhatsApp válido.');$vh=null;foreach($hor as$h)if($h['id']===$old['horario_id']){$vh=$h;break;}if(!$vh)throw new RuntimeException('Selecciona un horario válido.');$fi=null;if($tipo==='INTENSIVO'){if(!in_array($old['fecha_inicio'],$lunes,true))throw new RuntimeException('Selecciona un lunes válido.');$fi=$old['fecha_inicio'];}
$st=$pdo->prepare('SELECT id FROM alumnos WHERE sede_id=:s AND REPLACE(REPLACE(REPLACE(whatsapp," ",""),"-",""),"+","") LIKE :w LIMIT 1');$st->execute([':s'=>$sid,':w'=>'%'.$wa]);if($st->fetchColumn())throw new RuntimeException('Este WhatsApp ya tiene un registro en esta sede. Contacta a Hache para actualizarlo.');$admin=$pdo->query("SELECT id FROM usuarios WHERE rol='ADMIN' AND activo=1 ORDER BY created_at LIMIT 1")->fetchColumn();if(!$admin)throw new RuntimeException('No se pudo completar el registro.');$temp=(string)($pdo->query("SELECT valor FROM configuracion WHERE clave='password_temporal' LIMIT 1")->fetchColumn()?:'123456');$aid=uid($pdo);$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO alumnos(id,sede_id,nombre,fecha_nacimiento,whatsapp,correo,fecha_inicio,horario_preferido_id,plan_actual_id,estado_administrativo,observaciones) VALUES(:id,:s,:n,NULL,:w,NULL,:f,:h,NULL,'PENDIENTE',:o)");$st->execute([':id'=>$aid,':s'=>$sid,':n'=>$n,':w'=>$wa,':f'=>$fi?:date('Y-m-d'),':h'=>$vh['id'],':o'=>'Registro público '.$tipo.'. Pendiente de revisión/confirmación.']);$un=user($pdo,$n);$st=$pdo->prepare("INSERT INTO usuarios(id,usuario,password_hash,rol,activo,debe_cambiar_password,alumno_id) VALUES(:id,:u,:p,'ALUMNO',1,1,:a)");$st->execute([':id'=>uid($pdo),':u'=>$un,':p'=>password_hash($temp,PASSWORD_DEFAULT),':a'=>$aid]);$st=$pdo->prepare('INSERT INTO registros_publicos(id,alumno_id,sede_id,tipo,horario_id,fecha_inicio_intensivo) VALUES(:id,:a,:s,:t,:h,:f)');$st->execute([':id'=>uid($pdo),':a'=>$aid,':s'=>$sid,':t'=>$tipo,':h'=>$vh['id'],':f'=>$fi]);$pdo->commit();$_SESSION['csrf']=bin2hex(random_bytes(24));$ok=true;}catch(Throwable$x){if($pdo->inTransaction())$pdo->rollBack();$err=$x->getMessage();}}
$title=($tipo==='INTENSIVO'?'Curso intensivo':'Clases regulares').' · '.$sd['nombre'];?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=e($title)?> — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f7fb;color:#172033;font-family:system-ui,-apple-system,"Segoe UI",sans-serif}.w{max-width:560px;margin:auto;padding:28px 14px}.brand{font-size:12px;font-weight:900;letter-spacing:.12em;color:#123b5d;text-transform:uppercase}.hero{margin:24px 0 18px}.hero h1{font-size:32px;line-height:1.05;margin:0}.hero p{color:#64748b;line-height:1.5}.card{background:#fff;border:1px solid #dde5ee;border-radius:20px;padding:18px;box-shadow:0 12px 36px #0f172a10}.f{margin-bottom:15px}.f label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}.f input,.f select{width:100%;padding:13px;border:1px solid #cbd5e1;border-radius:11px;font:inherit;font-size:16px}.btn{width:100%;padding:14px;border:0;border-radius:12px;background:#172033;color:#fff;font-weight:900;font-size:16px}.err{background:#fff1f2;color:#9f1239;padding:12px;border-radius:11px;margin-bottom:14px}.ok{background:#fff;border:1px solid #bbf7d0;border-radius:20px;padding:24px}.ok b{font-size:25px}.ok p{color:#64748b;line-height:1.55}.hp{position:absolute;left:-9999px}</style></head><body><main class="w"><div class="brand">Hache Natación · <?=e($sd['nombre'])?></div><?php if($ok):?><section class="ok"><b>✓ Registro recibido</b><p>Gracias. Tu solicitud para <strong><?=e(strtolower($tipo==='INTENSIVO'?'curso intensivo':'clases regulares'))?></strong> fue registrada. Hache Natación revisará tu inscripción y confirmará los siguientes pasos.</p></section><?php else:?><header class="hero"><h1><?=e($tipo==='INTENSIVO'?'Curso intensivo':'Clases regulares')?></h1><p>Déjanos tus datos y el horario que prefieres. Solo necesitamos lo esencial.</p></header><section class="card"><?php if($err):?><div class="err"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input class="hp" name="website" tabindex="-1" autocomplete="off"><div class="f"><label>Nombre completo</label><input name="nombre" value="<?=e($old['nombre'])?>" required autocomplete="name"></div><div class="f"><label>WhatsApp</label><input name="whatsapp" value="<?=e($old['whatsapp'])?>" required inputmode="tel" autocomplete="tel" placeholder="998 123 4567"></div><div class="f"><label>Horario preferido</label><select name="horario_id" required><?php foreach($hor as$h):?><option value="<?=e($h['id'])?>" <?=$old['horario_id']===$h['id']?'selected':''?>><?=e(substr($h['hora_inicio'],0,5).' – '.substr($h['hora_fin'],0,5))?></option><?php endforeach;?></select></div><?php if($tipo==='INTENSIVO'):?><div class="f"><label>Lunes de inicio</label><select name="fecha_inicio" required><?php foreach($lunes as$d):?><option value="<?=e($d)?>" <?=$old['fecha_inicio']===$d?'selected':''?>><?=e(date('d/m/Y',strtotime($d)))?></option><?php endforeach;?></select></div><?php endif;?><button class="btn">Enviar registro</button></form></section><?php endif;?></main></body></html>